<script setup lang="ts">import{computed}from'vue';import type{FretboardNote,PitchClass,ScaleType}from'../domain/types';import{findScaleLocations}from'../domain/fretboard/fretboard';const props=defineProps<{tuning:readonly number[];root:PitchClass;scaleType:ScaleType;path:readonly FretboardNote[];current:FretboardNote|null;next:FretboardNote|null}>();const locations=computed(()=>findScaleLocations(props.tuning,props.root,props.scaleType));const key=(n:FretboardNote)=>`${n.stringIndex}:${n.fret}`;const pathKeys=computed(()=>new Set(props.path.map(key)));const x=(f:number)=>40+f*36;const y=(s:number)=>30+(props.tuning.length-1-s)*34;</script>
<template><div class="fretboard-scroll"><svg class="fretboard" :viewBox="`0 0 ${40+24*36+30} ${40+tuning.length*34}`" role="img" aria-label="Fretboard from fret 0 to 24"><g class="grid"><line v-for="s in tuning.length" :key="`s${s}`" x1="40" :x2="40+24*36" :y1="y(s-1)" :y2="y(s-1)"/><line v-for="f in 25" :key="`f${f}`" :x1="x(f-1)" :x2="x(f-1)" y1="18" :y2="y(0)+14"/><text v-for="f in 25" :key="`t${f}`" :x="x(f-1)" :y="y(0)+29">{{f-1}}</text></g><g><circle v-for="n in locations" :key="key(n)" :cx="x(n.fret)" :cy="y(n.stringIndex)" r="8" :class="{tone:true,path:pathKeys.has(key(n)),root:n.scaleDegree===1,current:current&&key(current)===key(n),next:next&&key(next)===key(n)}"/></g></svg></div></template>
